525	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
526	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
527	function parseHttpCode(out: string): number {
528	  const n = parseInt(out.trim().slice(-3), 10);
529	  return Number.isFinite(n) ? n : 0;
530	}
531	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
532	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
533	 *  (we never mark an account falsely healthy). */
534	function servesOk(code: number): boolean {
535	  return code >= 200 && code < 400;
536	}
537	
538	/**
539	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
540	 * curls http/https for each account's own Host header and records whether nginx
541	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
542	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
543	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
544	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
545	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
546	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
547	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
548	 * ~10-min tick. Returns the number of accounts processed.
549	 */
550	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
551	  const onlyRequested = opts.onlyRequested === true;
552	  if (SANDBOX) {
553	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
554	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
555	    const accts = await db.hostingAccount.findMany({
556	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
557	      select: { id: true, sslActive: true },
558	      take: onlyRequested ? 25 : 50,
559	    });
560	    for (const a of accts) {
561	      await db.hostingAccount.update({
562	        where: { id: a.id },
563	        data: {
564	          serveHttpOk: true,
565	          serveHttpsOk: true,
566	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
567	          healthCheckedAt: new Date(),
568	          recheckRequested: false,
569	        },
570	      }).catch(() => undefined);
571	    }
572	    return accts.length;
573	  }
574	  if (!ENABLED) return 0;
575	
576	  const accts = await db.hostingAccount.findMany({
577	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
578	    include: { node: true },
579	    // Newest-requested first so a customer who just clicked "Check now" is served
580	    // before the routine backlog even in the full sweep.
581	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
582	    take: onlyRequested ? 25 : 30,
583	  });
584	  let processed = 0;
585	  for (const a of accts) {
586	    try {
587	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
588	      const d = a.primaryDomain;
589	      const u = a.username;
590	      let serveHttpOk = false;
591	      let serveHttpsOk = false;
592	      let sslActive = a.sslActive;
593	      let note = "";
594	      const conn = await connectNode(a.node);
595	      try {
596	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
597	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
598	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
599	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
600	
601	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
602	        const liveDir = `/etc/letsencrypt/live/${d}`;
603	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
604	
605	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
606	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
607	        // re-verify. This is the recovery from exactly the state kaymo hit.
608	        if (haveReal && !serveHttpsOk) {
609	          const { webroot } = accountPaths(u);
610	          try {
611	            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
612	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
613	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
614	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
615	          } catch (e) {
616	            note = "HTTPS repair failed — support notified";
617	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
618	          }
619	        }
620	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
621	
622	        if (!note) {
623	          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
624	          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
625	          else {
626	            // Nothing served locally. If DNS isn't pointed at us yet, say so;
627	            // otherwise it's a serving fault the SSL sweep / support will chase.
628	            const pointed = await domainPointsAt(d, a.node.publicIp);
629	            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
630	          }
631	        }
632	      } finally {
633	        try { conn.end(); } catch { /* */ }
634	      }
635	      await db.hostingAccount.update({
636	        where: { id: a.id },
637	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
638	      });
639	      processed++;
640	    } catch (e) {
641	      console.error(`[hosting] health sweep ${a.id} failed`, e);
642	      // Clear the recheck flag even on failure so a broken node can't wedge the
643	      // fast path into re-processing the same account every 30s forever.
644	      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
645	    }
646	  }
647	  return processed;
648	}
